package com.rulecraft.decisionops.decisionapi.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="decision_api_request") public class DecisionApiRequest {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID serviceId;@Column(name="credential_id")private UUID credentialId;@Column(name="subject_key",nullable=false,length=80)private String subjectKey;@Column(name="client_request_id",nullable=false)private UUID clientRequestId;@Column(nullable=false,length=16)private String operation;@Column(name="request_hash",nullable=false,length=64)private String requestHash;@Column(name="deployment_id",nullable=false)private UUID deploymentId;@Column(name="decision_version_id",nullable=false)private UUID decisionVersionId;@Column(name="artifact_fingerprint",nullable=false,length=64)private String artifactFingerprint;@Column(name="item_count",nullable=false)private int itemCount;@Column(name="response_json",nullable=false,columnDefinition="text")private String responseJson;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="completed_at",nullable=false)private Instant completedAt;protected DecisionApiRequest(){}public DecisionApiRequest(UUID tenantId,UUID projectId,UUID serviceId,UUID credentialId,String subject,UUID clientId,String operation,String hash,UUID deploymentId,UUID versionId,String fingerprint,int count,String response,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.serviceId=serviceId;this.credentialId=credentialId;subjectKey=subject;clientRequestId=clientId;this.operation=operation;requestHash=hash;this.deploymentId=deploymentId;decisionVersionId=versionId;artifactFingerprint=fingerprint;itemCount=count;responseJson=response;createdAt=completedAt=now;}public UUID getId(){return id;}public String getOperation(){return operation;}public String getRequestHash(){return requestHash;}public String getResponseJson(){return responseJson;}public UUID getClientRequestId(){return clientRequestId;}public UUID getDeploymentId(){return deploymentId;}public UUID getDecisionVersionId(){return decisionVersionId;}public String getArtifactFingerprint(){return artifactFingerprint;}public int getItemCount(){return itemCount;}public Instant getCreatedAt(){return createdAt;}}
